mapper.select:
SELECT IFNULL(SUM(d.amount), 0)
FROM pur_instock_detail d
WHERE d.deleted = 0
  AND d.instock_id = #{instockId}
  AND d.material_id = #{materialId}

SELECT i.work_order_id, ii.material_id, m.code AS material_code, m.name AS material_name, SUM(ii.actual_qty) AS qty FROM mrp_material_issue i JOIN mrp_material_issue_item ii ON ii.issue_id = i.id AND ii.deleted = 0 LEFT JOIN base_material m ON m.id = ii.material_id WHERE i.deleted = 0 AND i.status = 'AUDITED' AND i.work_order_id IN
#{id}
GROUP BY i.work_order_id, ii.material_id, m.code, m.name

SELECT w.work_order_id, SUM(w.amount) AS amount, COUNT(*) AS line_count FROM hr_piece_wage_detail w WHERE w.deleted = 0 AND w.work_order_id IN
#{id}
GROUP BY w.work_order_id
